    _hits17.clear()
    assert engine.run_poc_on_target(_m_flow, _base_url17, {})[0]["poc_id"] == "smoke-flow"
    assert _hits17 == ["/a", "/b"], f"&& 两块都要跑：{_hits17}"
    # || 短路：第一块命中就不该再打第二块（省的是真实请求额度）
